css:
/* жорстко фіксуємо Times на всю форму */
.print-format, 
.print-format * {
  font-family: "Times New Roman", Times, serif !important;
  line-height: 1.25;

}
/* БАЗА: стабільний, “нестрибаючий” шрифт + щільне компонування */
.pf-wrap {
  color: #0f172a;
  padding: 8mm 10mm;           /* компактніше */
  line-height: 1.28;
  font-size: 14pt;
  position: relative;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

/* ВОДЯНИЙ ЗНАК "СПИСАНО" */
.pf-watermark {
  position: fixed;
  top: 40%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-22deg);
  font-size: 64px;
  font-weight: 900;
  color: rgba(220, 38, 38, 0.12);
  letter-spacing: 2px;
  z-index: 0;
  pointer-events: none;
}

/* ===== ШАПКА ===== */
.pf-header {
  margin-bottom: 6mm;
  border-bottom: 1px solid #e2e8f0;
  padding-bottom: 4mm;
}

/* Верхній рядок: назва на всю ширину + статус справа */
.pf-header-top {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 10px;
  margin-bottom: 6mm;
}
.pf-title {
  margin: 0;
  font-size: 20px;     /* 18–22px за бажанням */
  font-weight: 800;
  line-height: 1.2;
  word-break: break-word;
}
.pf-status {
  display: inline-block;
  white-space: nowrap;
  padding: 2px 10px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 12pt;
  border: 1px solid #e2e8f0;
  background: #f8fafc;
  color: #0f172a;
}

/* Сітка під назвою: фото | QR | мета */
.pf-header-grid {
  display: grid;
  grid-template-columns: 3fr 1.2fr 2.2fr;   /* фото / QR / мета */
  gap: 12px 16px;
  align-items: stretch;                      /* уніфікована висота колонок */
  min-height: 42mm;
  max-height: 58mm;                          /* не даємо фото розростись */
}

/* Фото: адаптивно по висоті колонки */
.pf-image-box {
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: #fff;
  height: 100%;
}
.pf-image-box img {
  height: 100%;
  width: auto;
  max-width: 100%;
  object-fit: contain;
}
.pf-image-ph { font-size: 14px; padding: 8px; }

/* QR-колонка */
.pf-qr-box {
  display: grid;
  grid-template-rows: auto auto;
  justify-items: center;
  align-content: start;
  gap: 6px;
}
.pf-qr-box img {
  width: 32mm; height: 32mm;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 1.5mm;
  background: #fff;
}
.pf-qr-caption {
  font-size: 10pt;
  text-align: center;
  word-break: break-all;
}

/* Метадані справа */
.pf-meta-box { display: grid; align-content: start; }
.pf-meta-lines { display: grid; gap: 4px; font-size: 10.5pt; }
.muted { color: #64748b; }

/* ===== СЕКЦІЇ / ПОЛЯ ===== */
.pf-section { margin-bottom: 5mm; position: relative; z-index: 2; }
.pf-section-title {
  font-size: 14pt;
  font-weight: 800;
  margin: 0 0 3mm 0;
  padding-bottom: 1.5mm;
  border-bottom: 1px solid #e2e8f0;
}

/* Сітка полів (дві колонки) */
.pf-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4mm 8mm;
}
@media print { .pf-grid { grid-template-columns: repeat(2, 1fr); } }
@media screen and (max-width: 820px) { .pf-grid { grid-template-columns: 1fr; } }

/* Пара “лейбл | значення” — щільно */
.pf-field { display: grid; grid-template-columns: 42% 58%; gap: 3px; }
.pf-label { font-weight: 600; font-size: 11pt; color: #334155; }
.pf-value { font-size: 11pt; color: #0f172a; word-break: break-word; }

/* ===== ТАБЛИЦЯ ===== */
.pf-table { width: 100%; border-collapse: collapse; font-size: 10.5pt; }
.pf-table th, .pf-table td { border: 1px solid #e2e8f0; padding: 4px 6px; vertical-align: top; }
.pf-table thead th { background: #f1f5f9; font-weight: 800; text-align: left; }

/* ===== ПІДПИСИ ===== */
.pf-signatures .pf-signature-rows {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10mm;
  margin-top: 4mm;
}
.sig-col { display: grid; gap: 4mm; }
.sig-line { border-bottom: 1px dashed #94a3b8; height: 10mm; }
.sig-caption { font-size: 10px; color: #475569; text-align: center; }

/* ===== ФУТЕР / ПАГІНАЦІЯ ===== */
.pf-footer {
  margin-top: 6mm;
  border-top: 1px solid #e2e8f0;
  padding-top: 3mm;
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: #475569;
}
@media print {
  .page-number:after { content: counter(page); }
  .page-count:after { content: counter(pages); }
}

/* Легкі підсвітки статусів (за потреби) */
.status-на-складі .pf-status { background: #ecfdf5; color: #065f46; border-color: #a7f3d0; }
.status-в-експлуатації .pf-status { background: #eff6ff; color: #1d4ed8; border-color: #bfdbfe; }
.status-передано .pf-status { background: #fff7ed; color: #9a3412; border-color: #fed7aa; }
.status-списано .pf-status { background: #fee2e2; color: #991b1b; border-color: #fecaca; }

/* Тонке узгодження, коли .pf-header-top поза .pf-header */
.pf-header-top{
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 10px;
  margin: 0 0 6mm 0;   /* відступ під назвою */
}
.pf-header{            /* лінія під сіткою, не дублюємо зайві відступи */
  margin-bottom: 6mm;
  padding-bottom: 4mm;
  border-bottom: 1px solid #e2e8f0;
}

/* (необов’язково) якщо хочеш лінію під назвою теж: */
.pf-header-top.with-divider{
  padding-bottom: 4mm;
  border-bottom: 1px solid #e2e8f0;
  margin-bottom: 4mm;  /* тоді .pf-header можна без border-bottom */
}

@page {
  @bottom-right {
    content: "Сторінка " counter(page) " з " counter(pages);
    font-size: 10px;
    color: #444;
  }
}

html:
{%- set meta = frappe.get_meta(doc.doctype) -%}
{%- set title_field = meta.title_field or "name" -%}
{%- set display_title = doc.get(title_field) or doc.name -%}
{%- set status = (doc.status or "").strip() -%}
{%- set status_class = ("status-" ~ (status|lower|replace(" ", "-"))) if status else "status-none" -%}
{%- set doc_url = frappe.utils.get_url_to_form(doc.doctype, doc.name) -%}

{%- macro field(label, value, df=None) -%}
  {%- if value not in (None, "", [], {}) -%}
    <div class="pf-field">
      <div class="pf-label">{{ label }}</div>
      <div class="pf-value">
        {%- if df -%}
          {{ frappe.format(value, df, doc) }}
        {%- else -%}
          {{ value }}
        {%- endif -%}
      </div>
    </div>
  {%- endif -%}
{%- endmacro -%}

{%- macro datefmt(value) -%}
  {{ frappe.format(value, {"fieldtype": "Date"}, doc) }}
{%- endmacro -%}

{# Повернути читабельний заголовок пов’язаного документа #}
{%- macro link_title(dt, name) -%}
  {%- if not dt or not name -%}—{%- else -%}
    {%- set lm = frappe.get_meta(dt) -%}
    {%- set tf = lm.title_field or "name" -%}
    {%- if tf == "name" -%}
      {{ name }}
    {%- else -%}
      {{ frappe.db.get_value(dt, name, tf) or name }}
    {%- endif -%}
  {%- endif -%}
{%- endmacro -%}

<div class="pf-wrap {{ status_class }}">
  {%- if status == "Списано" -%}
    <div class="pf-watermark">СПИСАНО</div>
  {%- endif -%}
    <!-- Верхній рядок: назва на всю ширину + статус справа -->
    <div class="pf-header-top">
      <h1 class="pf-title">{{ display_title }}</h1>
      <span class="pf-status">{{ status or "Без статусу" }}</span>
    </div>

  <!-- ШАПКА -->
  <div class="pf-header">

    <!-- Сітка: 1) фото 2) QR 3) метадані -->
    <div class="pf-header-grid">
      <!-- 1) Фото -->
      <div class="pf-image-box">
        {% if doc.image %}
          <img src="{{ doc.image }}" alt="Фото активу" />
        {% else %}
          <div class="pf-image-ph muted">Немає зображення</div>
        {% endif %}
      </div>
      <!-- 3) Метадані -->
      <div class="pf-meta-box">
        <div class="pf-meta-lines">
          <div><span class="muted">ID:</span> {{ doc.name }}</div>
          <div>Створено: {{ frappe.format(doc.creation, {"fieldtype":"Datetime"}) }}</div>
          <div>Оновлено: {{ frappe.format(doc.modified, {"fieldtype":"Datetime"}) }}</div>
        </div>
      </div>    
      <!-- 2) QR -->
      <div class="pf-qr-box">
        <img src='https://quickchart.io/qr?text={{ (doc_url|urlencode) }}' alt="QR"/>
        <div class="pf-qr-caption">
          <div>Відкрити документ</div>
          <div class="muted">{{ doc_url }}</div>
        </div>
      </div>

      
    </div>
  </div>

  <!-- ОСНОВНА ІНФОРМАЦІЯ -->
  <div class="pf-section">
    <h2 class="pf-section-title">Основна інформація</h2>
    <div class="pf-grid">
      {{ field("Інвентарний номер", doc.inventory_no, meta.get_field("inventory_no")) }}
      {{ field("Серійний номер", doc.serial_no, meta.get_field("serial_no")) }}

      {{ field("Модель", doc.hardware_model, meta.get_field("hardware_model")) }}

      {{ field("Поточний власник", doc.current_owner, meta.get_field("current_owner")) }}
      {{ field("Матеріально-відповідальна особа", doc.responsible_employee, meta.get_field("responsible_employee")) }}

      {{ field("Користувач", doc.asset_user, meta.get_field("asset_user")) }}
      {{ field("Місцезнаходження", doc.location, meta.get_field("location")) }}
    </div>
  </div>

  <!-- ІНФОРМАЦІЯ ПРО НАДХОДЖЕННЯ -->
  <div class="pf-section">
    <h2 class="pf-section-title">Інформація про надходження</h2>
    <div class="pf-grid">
      {{ field("Тип Активу", doc.asset_type, meta.get_field("asset_type")) }}
      {{ field("Дата надходження", doc.acquisition_date, meta.get_field("acquisition_date")) }}

      {{ field("Первинний Донор", doc.original_donor, meta.get_field("original_donor")) }}
      {{ field("Проєкт-джерело", doc.source_project, meta.get_field("source_project")) }}

      {{ field("Кількість", doc.quantity, meta.get_field("quantity")) }}
      {{ field("Вартість (за од.)", doc.cost, meta.get_field("cost")) }}
      {{ field("Сума", doc.total, meta.get_field("total")) }}
    </div>
  </div>

  <!-- ІСТОРІЯ ПЕРЕМІЩЕНЬ -->
  {%- set rows = doc.get("movement_history") or [] -%}
  {%- if rows -%}
  <div class="pf-section">
    <h2 class="pf-section-title">Історія переміщень</h2>
    <table class="pf-table">
      <thead>
        <tr>
          <th>Дата</th>
          <th>Тип руху</th>
          <th>Звідки</th>
          <th>Куди</th>
          <th>Підстава</th>
        </tr>
      </thead>
      <tbody>
        {%- for row in rows -%}
          <tr>
            <td>{{ datefmt(row.date) }}</td>
            <td>{{ row.movement_type }}</td>
            <td>
              {%- if row.from_source_name -%}
                {{ link_title(row.from_source_type, row.from_source_name) }}
              {%- else -%}
                —
              {%- endif -%}
            </td>
            <td>{{ link_title("oiOrganization", row.to_organization) if row.to_organization else "—" }}</td>
            <td>{{ link_title("oiBasisDoc", row.reference_appendix) if row.reference_appendix else "—" }}</td>
          </tr>
        {%- endfor -%}
      </tbody>
    </table>
  </div>
  {%- endif -%}
</div>
